@verbatim
<!doctype html><html lang="en"><head>
@endverbatim
<meta name="csrf-token" content="{{ csrf_token() }}">
@verbatim<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EazyPOS — Contact</title><meta name="description" content="Contact EazyPOS at help@eazyposs.store."><style> :root{--lime:#d3ff12;--lime2:#ecff4b;--ink:#0b0d0c;--soft:#f6f8f4;--muted:#727a73;--line:#e2e7df;--dark:#070908}*{box-sizing:border-box}body{margin:0;background:var(--soft);color:var(--ink);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.navbar{position:sticky;top:0;z-index:20;background:var(--lime);border-bottom:1px solid #b8dc00}.navin{max-width:1220px;height:76px;margin:auto;padding:0 22px;display:flex;align-items:center;justify-content:space-between}.brand{width:142px;height:auto}.navlinks{display:flex;gap:25px}.navlinks a{color:#0b0d0c;text-decoration:none;font-weight:850;font-size:14px}.nav-actions{display:flex;gap:8px}.pill,.get{border-radius:999px;padding:12px 16px;font-weight:900;text-decoration:none}.pill{border:1px solid #0b0d0c22;background:#ffffff45;color:#0b0d0c}.get{background:#0b0d0c;color:#fff}.wrap{max-width:1180px;margin:auto;padding:78px 22px}.hero{background:#070908;color:#fff;padding:80px 22px}.hero .inner{max-width:1180px;margin:auto}.kicker{color:#7a847b;font-size:11px;font-weight:950;letter-spacing:.12em;text-transform:uppercase}.hero .kicker{color:#d3ff12}.hero h1{font-size:clamp(48px,7vw,82px);line-height:.95;letter-spacing:-4px;margin:16px 0}.hero p{color:#aeb7ae;max-width:680px;font-size:18px;line-height:1.55}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{background:#fff;border:1px solid var(--line);border-radius:22px;padding:24px;box-shadow:0 15px 35px #0b0d0c08}.field{margin-bottom:16px}.field label{display:block;font-size:11px;font-weight:900;margin-bottom:7px}.field input,.field select,.field textarea{width:100%;padding:13px 14px;border:1px solid var(--line);border-radius:12px;background:#fff;font:inherit}.field textarea{min-height:140px;resize:vertical}.submit{border:0;background:var(--lime);color:#0b0d0c;border-radius:999px;padding:13px 18px;font-weight:950;cursor:pointer}.note{background:#eef1eb;border-radius:14px;padding:14px;color:#5f6861;font-size:13px}.testimonials{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.person{display:flex;align-items:center;gap:12px;margin-top:18px}.avatar{width:52px;height:52px;border-radius:50%;overflow:hidden;flex:0 0 auto}.avatar img{width:100%;height:100%;display:block}.tag{display:inline-block;background:var(--lime);color:#0b0d0c;border-radius:999px;padding:6px 9px;font-size:10px;font-weight:950}.quote{font-size:17px;line-height:1.6;margin:16px 0;color:#273029}.footer{background:#070908;color:#fff;padding:65px 22px 28px}.footergrid{max-width:1220px;margin:auto;display:grid;grid-template-columns:1.5fr repeat(4,1fr);gap:35px;padding-bottom:40px}.footerbrand img{width:165px}.footerbrand p{color:#8d968e;max-width:300px;font-size:13px;line-height:1.6}.footercol h4{margin:0 0 14px}.footercol a{display:block;color:#8e988f;text-decoration:none;font-size:13px;margin:10px 0}.socials{display:flex;gap:10px;margin-top:18px}.socials a{width:46px;height:46px;border:1px solid #ffffff30;background:#111512;border-radius:12px;color:#fff;display:grid;place-items:center}.socials svg{width:23px;height:23px}.footerbottom{max-width:1220px;margin:auto;border-top:1px solid #ffffff12;padding-top:20px;color:#707970;font-size:11px;display:flex;justify-content:space-between}.footerbottom a{color:var(--lime);text-decoration:none}@media(max-width:900px){.navlinks{display:none}.grid,.testimonials{grid-template-columns:1fr}.footergrid{grid-template-columns:1fr 1fr}.footerbrand{grid-column:1/-1}}@media(max-width:560px){.navin{height:64px;padding:0 14px}.brand{width:120px}.wrap{padding:60px 16px}.hero{padding:60px 16px}.hero h1{font-size:50px}.footergrid{grid-template-columns:1fr}.footerbrand{grid-column:auto}.footerbottom{flex-direction:column;gap:8px}}
/* Contact page responsive layout */
.contact-layout{grid-template-columns:minmax(0,1.2fr) minmax(260px,.8fr);align-items:start}
.contact-layout>div:last-child{display:grid;gap:16px;align-content:start}
.contact-layout>div:last-child .card{margin-top:0!important}
@media(max-width:900px){.contact-layout{grid-template-columns:1fr!important;gap:16px}.contact-layout>div:last-child{grid-template-columns:1fr 1fr;gap:12px}}
@media(max-width:560px){
  .hero{padding:40px 18px!important}
  .hero h1{font-size:clamp(38px,11vw,48px)!important;letter-spacing:-1.6px!important;line-height:1.02!important}
  .hero p{font-size:15px!important;line-height:1.5!important}
  .wrap{padding:28px 14px 42px!important}
  .contact-layout{gap:14px!important}
  .contact-layout>.card{padding:22px 18px!important;border-radius:18px!important}
  .contact-layout>div:last-child{grid-template-columns:1fr;gap:12px}
  .contact-layout h2{font-size:29px!important;letter-spacing:-.7px!important}
  .field{margin-bottom:12px!important}
  .field input,.field select,.field textarea{padding:12px!important;min-height:46px;font-size:15px!important}
  .field textarea{min-height:105px!important}
  .submit{width:100%;min-height:48px}
  .footer{padding:42px 16px 24px!important}
  .footergrid{gap:22px!important;padding-bottom:28px!important}
  .footerbrand img{width:145px!important;object-fit:contain!important;object-position:left center!important}
  .footerbottom{gap:8px!important;line-height:1.5}
}
</style></head><body><nav class="navbar"><div class="navin"><a href="/"><img class="brand" src="/assets/eazypos-logo-transparent.png" alt="EazyPOS"></a><div class="navlinks"><a href="/#features">Features</a><a href="/#how">How it works</a><a href="/#businesses">For businesses</a><a href="/#about">About</a><a href="/inquiry">Contact</a></div><div class="nav-actions"><a class="pill" href="/" onclick="return openLoginFromParent(event)">Log in</a><a class="get" href="/" onclick="return openSignupFromParent(event)">Get Started →</a></div></div></nav><main><section class="hero"><div class="inner"><div class="kicker">Contact EazyPOS</div><h1>Have a question?<br><span style="color:var(--lime)">Let's talk.</span></h1><p>Tell us what you need, what kind of business you run, or what you'd like to know about EazyPOS.</p></div></section><section class="wrap"><div class="grid contact-layout"><div class="card"><h2 style="font-size:38px;margin-top:0">Send us a message</h2><form id="inquiryForm" onsubmit="submitInquiry(event)"><div class="field"><label>NAME *</label><input name="name" required maxlength="120" placeholder="Your name"></div><div class="field"><label>EMAIL *</label><input name="email" required type="email" maxlength="255" placeholder="you@business.com"></div><div class="field"><label>BUSINESS</label><input name="business" maxlength="255" placeholder="Business name"></div><div class="field" style="position:absolute;left:-9999px" aria-hidden="true"><label>WEBSITE</label><input name="website" tabindex="-1" autocomplete="off"></div><div class="field"><label>WHAT CAN WE HELP WITH?</label><select name="topic"><option>General inquiry</option><option>Getting started</option><option>POS / Sales</option><option>Products & Stock</option><option>Reports & Register</option><option>Other</option></select></div><div class="field"><label>MESSAGE *</label><textarea id="message" name="message" required maxlength="5000" placeholder="Tell us a little about your question..."></textarea></div><button class="submit" type="submit">Send Inquiry →</button><p id="sent" class="note" style="display:none;margin-top:14px" aria-live="polite"></p></form></div><div><div class="card"><span class="tag">CONTACT</span><h3 style="font-size:28px">help@eazyposs.store</h3><p style="color:var(--muted);line-height:1.6">We're here for questions about setup, features, accounts and the EazyPOS workflow.</p><a class="get" href="mailto:help@eazyposs.store" style="display:inline-block">Email EazyPOS →</a></div><div class="card" style="margin-top:18px"><h3>What can you ask?</h3><p style="color:var(--muted);line-height:1.6">Ask about getting started, moving from another POS, products and stock, register reports, sales returns, or anything else you need clarified.</p></div></div></div></section></main><footer class="footer"><div class="footergrid"><div class="footerbrand"><img src="/assets/eazypos-logo-green.png" alt="EazyPOS"><p>A simple, modern POS built to help small businesses sell, track and grow with less effort.</p><p><a href="mailto:help@eazyposs.store" style="color:#d3ff12;text-decoration:none">help@eazyposs.store</a></p><div class="socials"><a href="https://www.instagram.com/eazyposs?stkn=MXM4dWo2b2FqYmtvNQ%3D%3D&amp;utm_source=qr" aria-label="Instagram" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="5" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="12" r="4.2" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="17.4" cy="6.7" r="1.2" fill="currentColor"/></svg></a><a href="https://www.facebook.com/share/1J4kpjqima/?mibextid=wwXIfr" aria-label="Facebook" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24"><path d="M14.2 21v-8h2.7l.4-3.1h-3.1V8c0-.9.3-1.5 1.6-1.5h1.7V3.7c-.3 0-1.4-.1-2.6-.1-2.6 0-4.4 1.6-4.4 4.5v1.8H7.8V13h2.7v8h3.7Z" fill="currentColor"/></svg></a><a href="#" aria-label="TikTok"><svg viewBox="0 0 24 24"><path d="M15.2 3c.3 2.1 1.5 3.4 3.6 3.6v3.2c-1.4-.1-2.6-.5-3.6-1.2v6.3c0 4-2.8 6.1-6 6.1-3 0-5.2-2.1-5.2-5 0-3.2 2.5-5.3 5.8-5.3.4 0 .8 0 1.2.1v3.2c-.4-.1-.7-.2-1.1-.2-1.2 0-2.3.7-2.3 2 0 1.1.8 2 2 2 1.4 0 2.1-.9 2.1-2.5V3h3.5Z" fill="currentColor"/></svg></a><a href="#" aria-label="LinkedIn"><svg viewBox="0 0 24 24"><path d="M5.2 8.2H2V21h3.2V8.2ZM3.6 3C2.6 3 2 3.7 2 4.6s.6 1.6 1.6 1.6 1.6-.7 1.6-1.6S4.6 3 3.6 3ZM21 13.7c0-3.9-2.1-5.7-5-5.7-2.3 0-3.3 1.3-3.8 2.2V8.2H9V21h3.2v-6.4c0-1.7.3-3.4 2.5-3.4 2.2 0 2.2 2 2.2 3.5V21H21v-7.3Z" fill="currentColor"/></svg></a></div></div><div class="footercol"><h4>Product</h4><a href="/#features">Features</a><a href="/#how">How it works</a><a href="/#businesses">For businesses</a><a href="/#about">Get Started</a></div><div class="footercol"><h4>Why EazyPOS?</h4><a href="/#features">Simple POS</a><a href="/#features">Stock & Purchases</a><a href="/#how">Register</a><a href="/#features">Reports</a></div><div class="footercol"><h4>Company</h4><a href="/#about">About Us</a><a href="/inquiry">Contact</a><a href="/#how">How It Works</a></div><div class="footercol"><h4>Account</h4><a href="/">Log in</a><a href="/inquiry?topic=getting-started#message">Request an account</a><a href="/#features">Free to start</a></div></div><div class="footerbottom"><span>© 2026 EazyPOS · Simple POS for small businesses</span><span><a href="mailto:help@eazyposs.store">help@eazyposs.store</a></span></div></footer>@endverbatim
<script>
const params=new URLSearchParams(location.search);
if(params.get('topic')==='getting-started'){const s=document.querySelector('#inquiryForm select[name="topic"]');if(s)s.value='Getting started';}
function openLoginFromParent(e){e.preventDefault();location.href='/login';return false}
function openSignupFromParent(e){e.preventDefault();const s=document.querySelector('#inquiryForm select[name="topic"]');if(s)s.value='Getting started';document.getElementById('message')?.focus();return false}
async function submitInquiry(e){
 e.preventDefault();
 const form=e.target,btn=form.querySelector('.submit'),note=document.getElementById('sent');
 const body=Object.fromEntries(new FormData(form).entries());
 btn.disabled=true;btn.style.opacity='.65';note.style.display='none';note.style.color='';
 try{
  const res=await fetch('/inquiry',{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').getAttribute('content'),'X-Requested-With':'XMLHttpRequest'},body:JSON.stringify(body)});
  const data=await res.json().catch(()=>({}));
  if(!res.ok)throw new Error(res.status===429?'Too many messages. Please wait a minute and try again.':(data.message||'Unable to send your inquiry. Please email help@eazyposs.store.'));
  note.textContent=data.message||'Thank you! We will contact you soon.';
  note.style.color='#23804d';form.reset();
 }catch(error){note.textContent=error.message;note.style.color='#b42318'}
 finally{note.style.display='block';btn.disabled=false;btn.style.opacity='1'}
}
</script>
@verbatim</body></html>

